/**
 * The embedded fonts: Noto Sans, in four faces, loaded the first time a PDF
 * needs a character the standard 14 fonts cannot set.
 *
 * Each face is a module of its own (generated by scripts/build-fonts.mjs),
 * so the page's bundle carries none of them until one is asked for, and a
 * document in plain Latin never loads them at all. Measuring and drawing are
 * synchronous, so a render that needs them waits for `loadUnicodeFonts`
 * first; until then such characters print as `?`, as they always did.
 */
import { TrueTypeFont } from "./truetype";

export type UnicodeFace = "regular" | "bold" | "italic" | "boldItalic";

const faces = new Map<UnicodeFace, TrueTypeFont>();
let loading: Promise<void> | null = null;

export const faceOf = (style: { bold?: boolean; italic?: boolean }): UnicodeFace =>
  style.bold ? (style.italic ? "boldItalic" : "bold") : style.italic ? "italic" : "regular";

/** The embedded font for a style, or null when the fonts are not loaded. */
export const unicodeFont = (style: { bold?: boolean; italic?: boolean }): TrueTypeFont | null =>
  faces.get(faceOf(style)) ?? null;

export const unicodeFontsReady = (): boolean => faces.size === 4;

/** Registers a face from its file. Used by the loader, and by tests that read the file from disk. */
export function registerUnicodeFont(face: UnicodeFace, bytes: Uint8Array): void {
  faces.set(face, new TrueTypeFont(bytes));
}

const fromBase64 = (base64: string): Uint8Array => Uint8Array.from(atob(base64), char => char.charCodeAt(0));

/** Loads all four faces, once; later calls share the first. */
export function loadUnicodeFonts(): Promise<void> {
  if (unicodeFontsReady()) return Promise.resolve();
  loading ??= Promise.all([
    import("./data/noto-sans-regular").then(module => registerUnicodeFont("regular", fromBase64(module.default))),
    import("./data/noto-sans-bold").then(module => registerUnicodeFont("bold", fromBase64(module.default))),
    import("./data/noto-sans-italic").then(module => registerUnicodeFont("italic", fromBase64(module.default))),
    import("./data/noto-sans-bold-italic").then(module =>
      registerUnicodeFont("boldItalic", fromBase64(module.default)),
    ),
  ]).then(
    () => undefined,
    failure => {
      loading = null;
      throw failure;
    },
  );
  return loading;
}
